    /// <summary>How a hard PC task goes well, said once with any of the above.</summary>
    public const string Method = "HOW TO DO A PC TASK WELL: 1) look before acting (read the current state with a read-only command); 2) anything that changes, moves or deletes: say in one line what will happen and let run_powershell ask the user; 3) do it in as few steps as possible, full paths, PowerShell 5.1 syntax; 4) check it worked by reading the state again; 5) answer in one or two lines: what changed, and how to undo it. If a step fails, read the error and fix the command once; don't repeat the same failing command.";

    /// <summary>The know-how for this message (at most two), or none.</summary>
    public static List<(string Name, string How)> For(string text)
    {
        var found = new List<(string, string)>();
        if (string.IsNullOrWhiteSpace(text) || text.Length > 600) return found;
        foreach (var p in Plays)
        {
            if (!p.When.IsMatch(text)) continue;
            found.Add((p.Name, p.How));
            if (found.Count == 2) break;
        }
        return found;
    }

    /// <summary>The know-how, written for the AI's instructions.</summary>
    public static string? Brief(string text)
    {
        var plays = For(text);
        if (plays.Count == 0) return null;
        return Method + "\n" + string.Join("\n", plays.Select(p => $"KNOW-HOW ({p.Name}, tested on Windows): {p.How}"));
    }
}
